from __future__ import annotations

"""Decide whether a file or folder name is safe to sync to OneDrive / SharePoint.

The desktop client watches a local folder and, before pushing each new name up
to the service, runs it through :class:`NameValidator`. A name that fails any
rule is parked locally with an error so the user can rename it; a name that
passes is queued for upload.

The validator also tracks names it has already accepted into a single sync
folder so it can flag collisions. OneDrive is case-insensitive but
case-preserving: it stores ``Report.txt`` exactly as typed, yet will not let a
second file named ``report.txt`` live next to it.
"""

from dataclasses import dataclass, field

from name_rules import (
    ends_with_space,
    find_illegal_chars,
    is_reserved_name,
)


@dataclass(frozen=True)
class ValidationResult:
    """Outcome of validating one name."""

    name: str
    ok: bool
    reasons: tuple[str, ...] = ()

    def is_valid(self) -> bool:
        return self.ok


def _trailing_reasons(name: str) -> list[str]:
    """Collect reasons related to how a name ends.

    Windows rejects a name that finishes with a space because the trailing
    whitespace is silently dropped and two different names would collapse.
    """

    reasons: list[str] = []
    if ends_with_space(name):
        reasons.append("name may not end with a space")
    return reasons


def check_name(name: str) -> ValidationResult:
    """Validate a single name against the static naming rules.

    This does not consider collisions with other names; that lives on
    :class:`NameValidator`, which also has the list of names already synced.
    """

    reasons: list[str] = []

    stripped = name.strip()
    if not stripped:
        reasons.append("name may not be empty")
        return ValidationResult(name=name, ok=False, reasons=tuple(reasons))

    illegal = find_illegal_chars(name)
    if illegal:
        joined = " ".join(illegal)
        reasons.append(f"name contains illegal characters: {joined}")

    if is_reserved_name(name):
        reasons.append("name is a reserved device name")

    reasons.extend(_trailing_reasons(name))

    return ValidationResult(name=name, ok=not reasons, reasons=tuple(reasons))


@dataclass
class NameValidator:
    """Stateful validator for one sync folder.

    Holds the set of names already accepted so new names can be checked for
    collisions in addition to the static rules.
    """

    _accepted: list[str] = field(default_factory=list)

    def existing_names(self) -> list[str]:
        return list(self._accepted)

    def _collides(self, name: str) -> bool:
        """True when ``name`` would clash with a name already accepted."""

        for existing in self._accepted:
            if name == existing:
                return True
        return False

    def validate(self, name: str) -> ValidationResult:
        """Validate ``name`` against static rules and existing-name collisions."""

        base = check_name(name)
        reasons = list(base.reasons)

        if base.ok and self._collides(name):
            reasons.append("name collides with an existing item")

        return ValidationResult(name=name, ok=not reasons, reasons=tuple(reasons))

    def accept(self, name: str) -> ValidationResult:
        """Validate ``name`` and, if it passes, record it as synced."""

        result = self.validate(name)
        if result.ok:
            self._accepted.append(name)
        return result

    def accept_all(self, names: list[str]) -> list[ValidationResult]:
        """Validate a batch of names in order, recording the ones that pass."""

        out: list[ValidationResult] = []
        for name in names:
            out.append(self.accept(name))
        return out


def validate_batch(names: list[str]) -> list[ValidationResult]:
    """Convenience wrapper that runs a fresh validator over ``names``."""

    validator = NameValidator()
    return validator.accept_all(names)

